def f(grid):
    n=len(grid[0]); p=grid[0].index(2)
    o=[[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if 0<=p-r<=r or ... : pass
    for r in range(p+1):
        for c in (p-r,p+r):
            if 0<=c<n: o[r][c]=2
    for r in range(n):
        for c in range(n):
            if o[r][c]==0 and (r-c-p)%4==0 and r+c>p and c-r<p:
                o[r][c]=1
    return o
